;(()=>{
const labels={en:{btn:'View project details',title:'OpenStack — Private Cloud Infrastructure',close:'Close',body:'Built a private cloud lab using Ubuntu 24.04, DevStack and OpenStack Horizon. Created virtual machine instances, configured virtual networks and floating IP addresses, and practiced security groups and SSH key pairs.',details:'Lab components: Ubuntu · DevStack · Horizon · Nova · Neutron · SSH · Security Groups. Screenshots are not included because no project images were supplied.'},ar:{btn:'عرض تفاصيل المشروع',title:'OpenStack — البنية التحتية للسحابة الخاصة',close:'إغلاق',body:'أنشأت مختبر سحابة خاصة باستخدام Ubuntu 24.04 وDevStack ولوحة OpenStack Horizon. جهزت أجهزة افتراضية وشبكات وعناوين Floating IP، وتدرّبت على مجموعات الأمان ومفاتيح SSH.',details:'مكوّنات المختبر: Ubuntu · DevStack · Horizon · Nova · Neutron · SSH · Security Groups. لم تُضف صور لأن صور المشروع غير متوفرة ضمن الملفات.'}};
let dialog;
function init(){const section=document.getElementById('projects');if(!section)return;const cards=[...section.querySelectorAll('h3')];const h=cards.find(x=>x.textContent.includes('OpenStack'));if(!h)return;const card=h.closest('.group');if(!card||card.querySelector('.openstack-detail-btn'))return;const lang=document.documentElement.lang==='ar'?'ar':'en';const t=labels[lang];const b=document.createElement('button');b.type='button';b.className='openstack-detail-btn';b.textContent=t.btn;b.onclick=()=>showDialog(lang);h.parentElement.appendChild(b)}
function showDialog(lang){if(dialog)dialog.remove();const t=labels[lang];dialog=document.createElement('div');dialog.className='openstack-modal-overlay';dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true');dialog.setAttribute('aria-label',t.title);const panel=document.createElement('div');panel.className='openstack-modal-panel';const title=document.createElement('h2');title.textContent=t.title;const body=document.createElement('p');body.textContent=t.body;const details=document.createElement('p');details.textContent=t.details;const close=document.createElement('button');close.type='button';close.textContent=t.close;close.className='openstack-modal-close';close.onclick=()=>{dialog.remove();dialog=null};panel.append(title,body,details,close);dialog.append(panel);dialog.addEventListener('click',e=>{if(e.target===dialog)close.click()});document.body.append(dialog);close.focus()}
const observer=new MutationObserver(()=>init());observer.observe(document.getElementById('root'),{subtree:true,childList:true});init();document.addEventListener('keydown',e=>{if(e.key==='Escape'&&dialog){dialog.remove();dialog=null}});
})();
